export const COLOR_SCHEME_LIST: ColorSchemeOption[] = Object.values(COLOR_SCHEMES);

export const SHAPE_OPTIONS: ShapeOption[] = [
  { id: 'circle', name: '円', iconName: 'Circle' },
  { id: 'star', name: '星', iconName: 'Star' },
  { id: 'sparkle', name: 'キラキラ', iconName: 'Sparkles' },
  { id: 'ring', name: 'リング', iconName: 'CircleDot' },
];

export const DEFAULT_SETTINGS: ParticleSettings = {
  count: 180,
  speed: 1.5,
  followStrength: 0.05,
  trailLength: 0.2,
  particleSize: 3.5,
  shape: 'sparkle',
  colorScheme: 'rainbow',
  isAttract: true,
  autoMovement: true,
};

export const SETTING_LIMITS = {
  count: { min: 40, max: 500, step: 10 },
  speed: { min: 0.2, max: 4.0, step: 0.1 },
  followStrength: { min: 0.01, max: 0.15, step: 0.01 },
  trailLength: { min: 0.05, max: 0.5, step: 0.05 },
  particleSize: { min: 1.5, max: 8.0, step: 0.5 },
} as const;

import { useEffect, useRef, useCallback } from 'react';
import { ParticleItem, ParticleSettings, CanvasSize, ParticleShape } from '../types';
import { COLOR_SCHEMES } from '../constants';

interface ParticleCanvasProps {
  settings: ParticleSettings;
  burstTrigger: number;
}

const ParticleCanvas = ({ settings, burstTrigger }: ParticleCanvasProps) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const particlesRef = useRef<ParticleItem[]>([]);
  const pointerPosRef = useRef<{ x: number; y: number; isDown: boolean; isActive: boolean }>({
    x: window.innerWidth / 2,
    y: window.innerHeight / 2,
    isDown: false,
    isActive: false,
  });
  const autoAngleRef = useRef<number>(0);
  const canvasSizeRef = useRef<CanvasSize>({
    width: window.innerWidth,
    height: window.innerHeight,
  });

  // ランダムカラー取得
  const getRandomColor = useCallback(() => {
    const palette = COLOR_SCHEMES[settings.colorScheme]?.colors || COLOR_SCHEMES.rainbow.colors;
    return palette[Math.floor(Math.random() * palette.length)];
  }, [settings.colorScheme]);

  // 新規パーティクル生成
  const createParticle = useCallback(
    (x?: number, y?: number, isBurst = false): ParticleItem => {
      const width = canvasSizeRef.current.width;
      const height = canvasSizeRef.current.height;
      const posX = x ?? Math.random() * width;
      const posY = y ?? Math.random() * height;

      let vx = (Math.random() - 0.5) * settings.speed;
      let vy = (Math.random() - 0.5) * settings.speed;

      if (isBurst) {
        const angle = Math.random() * Math.PI * 2;
        const burstSpeed = (Math.random() * 8 + 3) * settings.speed;
        vx = Math.cos(angle) * burstSpeed;
        vy = Math.sin(angle) * burstSpeed;
      }

      return {
        x: posX,
        y: posY,
        vx,
        vy,
        size: (Math.random() * 0.8 + 0.6) * settings.particleSize * (isBurst ? 1.3 : 1),
        color: getRandomColor(),
        alpha: Math.random() * 0.5 + 0.5,
        maxLife: isBurst ? Math.floor(Math.random() * 60 + 60) : 999999,
        currentLife: 0,
        shape: settings.shape,
        spin: Math.random() * Math.PI * 2,
        spinSpeed: (Math.random() - 0.5) * 0.08,
      };
    },
    [settings.particleSize, settings.shape, settings.speed, getRandomColor]
  );

  // 設定に基づくパーティクル配列のリサイズ
  useEffect(() => {
    const current = particlesRef.current;
    if (current.length < settings.count) {
      const needed = settings.count - current.length;
      const newItems: ParticleItem[] = [];
      for (let i = 0; i < needed; i++) {
        newItems.push(createParticle());
      }
      particlesRef.current = [...current, ...newItems];
    } else if (current.length > settings.count) {
      particlesRef.current = current.slice(0, settings.count);
    }
  }, [settings.count, createParticle]);

  // 色や形状が切り替わった際に既存パーティクルも滑らかに更新
  useEffect(() => {
    particlesRef.current.forEach((p) => {
      p.shape = settings.shape;
      p.color = getRandomColor();
    });
  }, [settings.shape, settings.colorScheme, getRandomColor]);

  // バースト発火処理
  useEffect(() => {
    if (burstTrigger === 0) return;
    const { x, y } = pointerPosRef.current;
    const burstCount = 65;
    const bursts: ParticleItem[] = [];
    for (let i = 0; i < burstCount; i++) {
      bursts.push(createParticle(x, y, true));
    }
    particlesRef.current = [...particlesRef.current, ...bursts];
  }, [burstTrigger, createParticle]);

  // 形状描画補助関数
  const drawParticleShape = (
    ctx: CanvasRenderingContext2D,
    shape: ParticleShape,
    size: number
  ) => {
    switch (shape) {
      case 'circle': {
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, Math.PI * 2);
        ctx.fill();
        break;
      }
      case 'star': {
        ctx.beginPath();
        const spikes = 5;
        const outerRadius = size * 1.3;
        const innerRadius = size * 0.55;
        let rot = (Math.PI / 2) * 3;
        const step = Math.PI / spikes;
        let sx = 0;
        let sy = -outerRadius;
        ctx.moveTo(sx, sy);
        for (let i = 0; i < spikes; i++) {
          sx = Math.cos(rot) * outerRadius;
          sy = Math.sin(rot) * outerRadius;
          ctx.lineTo(sx, sy);
          rot += step;

          sx = Math.cos(rot) * innerRadius;
          sy = Math.sin(rot) * innerRadius;
          ctx.lineTo(sx, sy);
          rot += step;
        }
        ctx.closePath();
        ctx.fill();
        break;
      }
      case 'sparkle': {
        ctx.beginPath();
        const s = size * 1.5;
        ctx.moveTo(0, -s);
        ctx.quadraticCurveTo(0, 0, s, 0);
        ctx.quadraticCurveTo(0, 0, 0, s);
        ctx.quadraticCurveTo(0, 0, -s, 0);
        ctx.quadraticCurveTo(0, 0, 0, -s);
        ctx.closePath();
        ctx.fill();
        break;
      }
      case 'ring': {
        ctx.beginPath();
        ctx.arc(0, 0, size * 1.1, 0, Math.PI * 2);
        ctx.lineWidth = Math.max(1.5, size * 0.3);
        ctx.stroke();
        break;
      }
    }
  };

  // メインアニメーションループ
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let animationFrameId: number;

    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.scale(dpr, dpr);
      canvasSizeRef.current = { width, height };

      // パーティクルが画面外になりすぎないよう初期化
      if (particlesRef.current.length === 0) {
        const initialList: ParticleItem[] = [];
        for (let i = 0; i < settings.count; i++) {
          initialList.push(createParticle());
        }
        particlesRef.current = initialList;
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    const render = () => {
      const { width, height } = canvasSizeRef.current;

      // 残像効果のトレイル描画（黒背景を半透明で塗る）
      ctx.fillStyle = `rgba(10, 12, 22, ${settings.trailLength})`;
      ctx.fillRect(0, 0, width, height);

      // 加算合成で美しい光の重なりを表現
      ctx.globalCompositeOperation = 'lighter';

      // 自律周回ポイントの計算
      autoAngleRef.current += 0.015 * settings.speed;
      let targetX = pointerPosRef.current.x;
      let targetY = pointerPosRef.current.y;

      if (settings.autoMovement && !pointerPosRef.current.isActive) {
        const radiusX = Math.min(width, height) * 0.3;
        const radiusY = Math.min(width, height) * 0.22;
        targetX = width / 2 + Math.cos(autoAngleRef.current) * radiusX;
        targetY =
          height / 2 +
          Math.sin(autoAngleRef.current * 1.3) * radiusY +
          Math.cos(autoAngleRef.current * 0.6) * 30;
      }

      const isAttract = settings.isAttract;
      const followForce = settings.followStrength * (pointerPosRef.current.isDown ? 2.2 : 1.0);

      // パーティクル更新 & 描画
      const survivingParticles: ParticleItem[] = [];

      for (let i = 0; i < particlesRef.current.length; i++) {
        const p = particlesRef.current[i];
        p.currentLife += 1;

        // 寿命を迎えたバーストパーティクルは破棄
        if (p.currentLife > p.maxLife) {
          continue;
        }

        // 追従／反発の力学計算
        const dx = targetX - p.x;
        const dy = targetY - p.y;
        const distSq = dx * dx + dy * dy;
        const dist = Math.sqrt(distSq) || 1;

        if (distSq < 900000) {
          const force = Math.min(12, (100 / dist) * followForce);
          const dir = isAttract ? 1 : -1.2;
          p.vx += (dx / dist) * force * dir;
          p.vy += (dy / dist) * force * dir;
        }

        // 空気抵抗
        p.vx *= 0.94;
        p.vy *= 0.94;

        // 速度更新
        p.x += p.vx;
        p.y += p.vy;

        // 回転更新
        p.spin += p.spinSpeed;

        // 画面端の跳ね返り
        if (p.x < 0) {
          p.x = 0;
          p.vx *= -0.8;
        } else if (p.x > width) {
          p.x = width;
          p.vx *= -0.8;
        }
        if (p.y < 0) {
          p.y = 0;
          p.vy *= -0.8;
        } else if (p.y > height) {
          p.y = height;
          p.vy *= -0.8;
        }

        // 描画アルファ計算（バーストはフェードアウト）
        let alpha = p.alpha;
        if (p.maxLife < 999999) {
          alpha = p.alpha * (1 - p.currentLife / p.maxLife);
        }

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.spin);
        ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
        ctx.fillStyle = p.color;
        ctx.strokeStyle = p.color;

        drawParticleShape(ctx, p.shape, p.size);
        ctx.restore();

        survivingParticles.push(p);
      }

      particlesRef.current = survivingParticles;
      ctx.globalCompositeOperation = 'source-over';

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
    };
  }, [settings, createParticle]);

  // ポインターイベントハンドラー
  const handlePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    pointerPosRef.current = {
      x: e.clientX,
      y: e.clientY,
      isDown: true,
      isActive: true,
    };
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    pointerPosRef.current.x = e.clientX;
    pointerPosRef.current.y = e.clientY;
    pointerPosRef.current.isActive = true;
  };

  const handlePointerUp = () => {
    pointerPosRef.current.isDown = false;
  };

  const handlePointerLeave = () => {
    pointerPosRef.current.isDown = false;
    pointerPosRef.current.isActive = false;
  };

  return (
    <div className="canvas-container">
      <canvas
        ref={canvasRef}
        className="particle-canvas"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerLeave}
        onPointerCancel={handlePointerLeave}
      />
    </div>
  );
};

export default ParticleCanvas;

import { X, Sparkles, RefreshCw, Zap } from 'lucide-react';
import { ParticleSettings, ColorSchemeId, ParticleShape } from '../types';
