        </div>
      </div>

      {/* 自律周回運動 */}
      <div className="control-group">
        <label className="control-label">
          <span>自律オービット運動</span>
        </label>
        <div className="radio-group">
          <button
            type="button"
            className={`radio-btn ${settings.autoMovement ? 'radio-btn-active' : ''}`}
