          type="range"
          className="slider-input"
          min={SETTING_LIMITS.count.min}
          max={SETTING_LIMITS.count.max}
          step={SETTING_LIMITS.count.step}
          value={settings.count}
          onChange={(e) => onUpdateSettings({ count: Number(e.target.value) })}
        />
      </div>

