import { useState, useCallback } from 'react';
import { SlidersHorizontal, Sparkles, Zap } from 'lucide-react';
import ParticleCanvas from './components/ParticleCanvas';
import ControlPanel from './components/ControlPanel';
import { ParticleSettings } from './types';
import { DEFAULT_SETTINGS } from './constants';
import './index.css';

const App = () => {
  const [settings, setSettings] = useState<ParticleSettings>(DEFAULT_SETTINGS);
  const [isPanelOpen, setIsPanelOpen] = useState<boolean>(false);
  const [burstTrigger, setBurstTrigger] = useState<number>(0);

  const handleUpdateSettings = useCallback((newSettings: Partial<ParticleSettings>) => {
    setSettings((prev) => ({ ...prev, ...newSettings }));
  }, []);

  const handleBurst = useCallback(() => {
    setBurstTrigger((prev) => prev + 1);
  }, []);

  const handleReset = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
  }, []);

  const togglePanel = useCallback(() => {
    setIsPanelOpen((prev) => !prev);
  }, []);

  return (
    <div className="app-container">
      {/* メインパーティクルキャンバス背景 */}
      <ParticleCanvas settings={settings} burstTrigger={burstTrigger} />

      {/* UI オーバーレイ層 */}
      <div className="ui-overlay">
        {/* ヘッダーエリア */}
        <header className="header-panel">
          <div className="title-wrapper">
            <h1 className="app-title">
              <Sparkles size={20} />
              ルミナス・パーティクル
            </h1>
            <p className="app-subtitle">
              指先・カーソルに集う幻想の光シミュレーター
            </p>
          </div>

          <div className="toolbar-panel">
            <button
              type="button"
              className="btn btn-burst"
              onClick={handleBurst}
              title="星屑の爆発エフェクト"
            >
              <Zap size={16} />
              バースト
            </button>

            <button
              type="button"
              className="panel-toggle-btn"
              onClick={togglePanel}
              aria-expanded={isPanelOpen}
              aria-label="シミュレーション設定の切り替え"
            >
              <SlidersHorizontal size={16} />
              <span>設定</span>
            </button>
          </div>
        </header>

        {/* コントロール設定パネル */}
        <ControlPanel
          isOpen={isPanelOpen}
          onClose={() => setIsPanelOpen(false)}
          settings={settings}
          onUpdateSettings={handleUpdateSettings}
          onBurst={handleBurst}
          onReset={handleReset}
        />

        {/* フッター操作ガイド */}
        <footer className="footer-hint">
          画面上をドラッグまたはタップすると粒子が集まります / クリックで波紋が広がります
        </footer>
      </div>
    </div>
  );
};

export default App;
